"""Invoice line calculations. See README.md for the specification."""

from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def _line_total_decimal(unit_price, qty, discount_pct=0.0):
    if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
        raise ValueError("qty must be an int >= 1")
    if not 0 <= discount_pct <= 100:
        raise ValueError("discount_pct must be between 0 and 100")
    if unit_price < 0:
        raise ValueError("unit_price must be >= 0")

    price = Decimal(str(unit_price))
    discount = Decimal(str(discount_pct))
    total = price * qty * (1 - discount / 100)
    return total.quantize(CENT, rounding=ROUND_HALF_UP)


def line_total(unit_price, qty, discount_pct=0.0):
    return float(_line_total_decimal(unit_price, qty, discount_pct))


def invoice_total(lines):
    total = sum(
        (_line_total_decimal(price, qty, discount) for price, qty, discount in lines),
        Decimal("0"),
    )
    return float(total.quantize(CENT, rounding=ROUND_HALF_UP))

